/* ===== Данные слов (зашифрованы). Сгенерировано scripts/build-public.js ===== */
var WEEKS = (function () {
  var K = '5-words-a-day-2026';
  var B = '';
  try {
    var raw = atob(B);
    var bytes = new Uint8Array(raw.length);
    for (var i = 0; i < raw.length; i++) bytes[i] = raw.charCodeAt(i);
    var k = new Uint8Array(K.length);
    for (var j = 0; j < K.length; j++) k[j] = K.charCodeAt(j);
    for (var m = 0; m < bytes.length; m++) bytes[m] ^= k[m % k.length];
    return JSON.parse(new TextDecoder('utf-8').decode(bytes));
  } catch (e) {
    console.error('Не удалось расшифровать слова', e);
    return [];
  }
})();
